def binary_search(a, target):
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if a[mid] == target:
            return mid
        if a[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

def newton(f, df, x0, tol=1e-10, itmax=50):
    x = x0
    for _ in range(itmax):
        fx = f(x)
        if abs(fx) < tol:
            return x
        x = x - fx / df(x)
    return x
